"""Coordinate angle, vector length, two diagonals, an unknown multiplier and acute median angle on page 292."""
import argparse
import json
from math import sqrt
from coordinate_positions import panel
from scalar_coordinates import coordinate_card
from scalar_geometry import copy_figure, visual_card
from scalar_product import common_view
from trigonometric_signs import grade
from vector_scaling import BOOK, ROOT

OUT=ROOT/'geometry-course/textbook/data/additional-scalar-vectors.json'


def page292(card):
    card['source'].update(printedPages=[292],pdfPages=[293])
    card['review']['reviewer']='Условие и все обозначения сверены с печатной с. 292, издание Атанасяна 2023. Все значения на исходных и изменённых рисунках проверены независимым вычислением.'
    return card


def coordinates():
    pts={'A':(3,0),'B':(1,5),'C':(2,1)}
    def tri(label,p,start):return panel(label,p,'AB BC CA',' '.join(start+k for k in 'ABC' if k!=start))
    views=[tri('Сравни две стрелки из A',pts,'A'),tri('Сравни две стрелки из C',pts,'C'),tri('Перемести C в (3;5)',{**pts,'C':(3,5)},'C')]
    hint='Построй обе стрелки из проверяемой вершины. У тупого угла их произведение отрицательно. Косинус равен произведению, разделённому на произведение длин.'
    e=coordinate_card(1154,None,'У ABC вершины A=(3;0), B=(1;5), C=(2;1). Докажи, что он тупоугольный, найди косинус его тупого угла.',
        'При C имеем CA=(1;−1), CB=(−1;4). Их произведение −1−4=−5, поэтому C тупой. Длины CA=√2, CB=√17. Получаем cos C=−5/√34=−5√34/34.',hint,[
        ('Ищи отрицательное произведение','При A стрелки AB=(−2;5), AC=(−1;1) дают 7>0. При B стрелки BA=(2;−5), BC=(1;−4) дают 22>0. Таким образом, если угол тупой, его вершина C.','Векторы должны иметь одно и то же начало в вершине угла.'),
        ('Проверь угол C и нормируй','CA·CB=−5, обе длины положительны, значит cos C отрицателен. Их произведение √34, поэтому cos C=−5/√34. Рационализация знаменателя не меняет значения.','Скалярное произведение −5 само по себе не может быть косинусом.'),
        ('Смени третью точку','При C=(3;5) отрезок CA вертикален и CB горизонтален. Теперь их произведение 0 и угол C прямой.','Положение вершины определяет обе исходящие стрелки.')],views,[
        ('Каков числитель CA·CB в исходной фигуре?','-5','Сложи 1·(−1) и (−1)·4.'),('Каково новое CA·CB при C=(3;5)?','0','Горизонтальная и вертикальная стрелки взаимно перпендикулярны.')])
    e=grade(page292(e),['-5/√34','−5/√34','-5/sqrt(34)','-5√34/34','-5*sqrt(34)/34'],hint,'Введи точный косинус. Символ √ можно заменить на sqrt(…).')
    views=[panel('Три вправо и четыре вниз',{'M':(3,-4),'H':(3,0)},'OH HM','OM',['OHM']),
           panel('Поменяй направление вертикального шага',{'M':(3,4),'H':(3,0)},'OH HM','OM',['OHM']),
           panel('Удвоенная стрелка',{'M':(6,-8),'H':(6,0)},'OH HM','OM',['OHM'])]
    hint='Координатные i и j — взаимно перпендикулярные единичные векторы. Из коэффициентов 3 и −4 получаются катеты длиной 3 и 4.'
    f=coordinate_card(1155,None,'Какова длина вектора a=3i−4j в ортонормированном координатном базисе i,j?',
        'Стрелка имеет координаты (3;−4). Поэтому |a|=√(3²+(−4)²)=√25=5.',hint,[
        ('Наметь конечную точку','От O отложи три единицы вправо и четыре вниз. Стрелка OM является гипотенузой прямоугольного треугольника с вершиной H на оси x.','Знак −4 отвечает за направление вниз, длина вертикального катета равна 4.'),
        ('Вычисли модуль','Сумма квадратов 9+16=25, после извлечения корня получаем 5. У отражённого вектора 3i+4j результат такой же.','Нельзя складывать подписанные координаты и считать это длиной.'),
        ('Вдвое увеличь все смещения','Для 6i−8j модуль √(36+64)=10. Это вдвое больше прежнего модуля.','Если обе координаты умножены на 2, длина тоже умножается на 2.')],views,[
        ('Каков квадрат длины (3;4)?','25','Сложи 3² и 4².'),('Чему равна длина (6;−8)?','10','Извлеки корень из 100.')])
    return [e,grade(page292(f),['5','5,0','5.0'],hint,'Введи длину вектора одним числом.')]


def add(a,b):return (a[0]+b[0],a[1]+b[1])
def mul(k,a):return (k*a[0],k*a[1])

def diagonal_scene(label,p,q,full):
    if not full:return copy_figure(label,{'O':(0,0),'P':p,'Q':q},'OP OQ','')
    a=add(mul(5,p),mul(2,q));b=add(p,mul(-3,q));s=add(a,b)
    return copy_figure(label,{'O':(0,0),'A':a,'B':b,'S':s},'OS BA','OA AS SB BO')


def diagonals():
    views=[diagonal_scene('Базовые p и q под углом 45°',(2,2),(3,0),False),diagonal_scene('Диагонали OS и BA', (2,2),(3,0),True),
           diagonal_scene('Сделай p и q перпендикулярными',(0,2*sqrt(2)),(3,0),True)]
    hint='Диагонали представляются a+b=6p−q и a−b=4p+5q. Сначала вычисли p·q по данным о длинах и угле: нужен множитель cos 45°.'
    e=visual_card(1156,[292],'Стороны параллелограмма заданы векторами a=5p+2q, b=p−3q. Известны |p|=2√2, |q|=3, угол между p и q равен 45°. Найди длины диагоналей в порядке |a+b|, |a−b|.',
        'p·q=(2√2)·3·cos 45°=6. Квадрат первой диагонали |6p−q|²=36·8−12·6+9=225. Квадрат второй |4p+5q|²=16·8+40·6+25·9=593. Длины 15 и √593≈24,35.',hint,[
        ('Сложи и вычти заданные стороны','a+b=(5+1)p+(2−3)q=6p−q. Для a−b получаем (5−1)p+(2+3)q=4p+5q. В основании рисунка можно взять p=(2;2), q=(3;0).','При вычитании b знак у −3q меняется.'),
        ('Отдельно раскрой два квадрата','У |6p−q|² смешанный член −12p·q=−72. У |4p+5q|² он +40p·q=240. После сложения квадратов и извлечения корней получаем 15 и √593.','Модули p и q перед подстановкой в их скалярные квадраты нужно возвести в квадрат.'),
        ('Удали смешанные члены новым углом','Если p⊥q при прежних длинах, два квадрата равны 36·8+9=297 и 16·8+25·9=353. Изменение угла повлияло на обе диагонали по-разному.','Коэффициенты при p,q не изменились, изменилось их произведение.')],views,[
        ('Каково p·q в исходном параллелограмме?','6','Умножь 2√2 на 3 и на √2/2.'),('Чему равен новый квадрат |a−b|² при p⊥q?','353','Сложи 16·8 и 25·9.')],[110,112],'Первый чертёж показывает p и q. Следующие показывают параллелограмм OASB, где OA=a и OB=b. Две выделенные диагонали — OS и BA.')
    return grade(e,['15;√593','15;sqrt(593)','15;24,35','15;24.35','15;24,4','15;24.4'],hint,'Введи две длины через точку с запятой. Вторую можно записать корнем или округлить до сотых.')


def perpendicular_parameter():
    a=(2,0);b=(-2.5,5*sqrt(3)/2)
    q=add(mul(3,a),mul(-1,b))
    def sample(x,label):
        p=add(mul(x,a),mul(17,b))
        return common_view(label,mul(.05,p),mul(.5,q))
    views=[copy_figure('Исходный угол 120°',{'O':(0,0),'A':a,'B':b},'OA OB',''),
           sample(40,'Две укороченные стрелки при x=40'),sample(20,'Проверь пробное x=20')]
    hint='Раскрой (xa+17b)·(3a−b). Учитывай a·b=2·5·cos 120°=−5 и условие, что искомое скалярное произведение ноль.'
    e=visual_card(1157,[292],'При каком x перпендикулярны p=xa+17b и q=3a−b, если |a|=2, |b|=5 и угол между a и b равен 120°?',
        'p·q=x(3|a|²−a·b)+17(3a·b−|b|²)=x(12+5)+17(−15−25)=17x−680. Приравнивая нулю, получаем x=40. Векторы ненулевые: исходные a,b неколлинеарны.',hint,[
        ('Прочитай исходные произведения','|a|²=4, |b|²=25, a·b=−5. Множитель при x в раскрытой формуле равен 3·4−(−5)=17.','Отрицательный косинус меняет знак смешанного произведения.'),
        ('Реши линейное уравнение','Оставшееся слагаемое 17(3·(−5)−25)=−680. Отсюда x=680/17=40. Чтобы чертёж поместился, во второй модели p показан в масштабе 1:20, q — 1:2. Положительное укорочение каждой стрелки сохраняет угол.','Проверь подстановку: 17·40−680=0.'),
        ('Проверь новое значение x','При x=20 исходное p·q=340−680=−340. Угол уже тупой. Произведение отображённых укороченных стрелок равно −340/40=−8,5 и имеет тот же знак.','На изменённом чертеже направления реальны, но численный модуль произведения требует учитывать оба масштаба.')],views,[
        ('Каков коэффициент при x в p·q?','17','Вычисли 3·4−(−5).'),('Чему равно произведение полных векторов при x=20?','-340','Вычисли 17·20−680.')],[110,111,112],'В исходном рисунке OA=a и OB=b. Во втором и третьем PX=p/20, PY=q/2; обе шкалы положительны и сохраняют угол.')
    return grade(e,['40','40,0','40.0'],hint,'Введи значение x.')


def acute_medians():
    def model(label,x,y):
        return copy_figure(label,{'A':(0,0),'B':(x,0),'C':(0,y),'H':(0,y/2),'K':(x/2,0),'G':(x/3,y/3)},'BH CK','AB BC CA')
    views=[model('Равные катеты по 2',2,2),model('Равные катеты по 4',4,4),model('Другой прямоугольный треугольник с катетами 4 и 2',4,2)]
    hint='Вычисли скалярное произведение векторов двух медиан. Если оно отрицательное, направленные стрелки образуют тупой угол. Для острого угла прямых используй модуль косинуса. У arccos(4/5) дробная часть градуса даёт 52,19 минуты: округли до 52′.'
    e=visual_card(1158,[292],'В прямоугольном равнобедренном треугольнике проведены медианы из вершин двух острых углов. Найди острый угол между этими медианами с точностью до минуты.',
        'По подобию достаточно взять катеты по 2. Из B=(2;0) медиана направлена к H=(0;1), из C=(0;2) к K=(1;0). Направляющие (−2;1) и (1;−2) имеют произведение −4 и длины √5. Для острого угла cos φ=4/5. Поэтому φ=arccos(0,8)≈36,8699°≈36°52′. В ответах на с. 400 приведено 36°51′; округление ближайшей минуты даёт 52′.',hint,[
        ('Найди точные направления','H и K — середины противоположных катетов. Разность координат конца и начала даёт BH=(−2;1), CK=(1;−2). Их произведение −4.','Заменять середины на концы катетов нельзя: это дало бы стороны треугольника.'),
        ('Выбери острый из двух углов','У двух выбранных стрелок косинус −4/5. У острого смежного угла косинус 4/5. При удвоении всех длин угол прежний. Калькулятор даёт 36,869897…°; дробная часть, умноженная на 60, равна 52,1938… минуты.','Число 0,8699 градуса не равно 86,99 минуты.'),
        ('Проверь необходимость равнобедренности','Пусть катеты теперь 4 и 2. Получаем BH=(−4;1), CK=(2;−2), произведение −10, квадраты длин 17 и 8. Тогда cos² острого угла=100/136=25/34, вместо исходных 16/25.','Равное масштабирование и растягивание одной стороны по-разному меняют угол.')],views,[
        ('Какой числитель у сокращённой дроби cos φ=…/5 для исходного острого угла?','4','Для острого угла возьми модуль произведения.'),('Какой знаменатель у новой сокращённой дроби cos²φ=25/…?','34','Сократи 100/136 на 4.')],[110,111],'H — середина AC, K — середина AB. Сравни направления медиан BH и CK и отметь острый угол при их пересечении G.')
    e['review']['reviewer']+=' Проверены исходник с. 292 и округление ответа на с. 400.'
    return grade(e,['36°52′',"36°52'",'36:52','36 52','arccos(4/5)'],hint,'Введи угол до минуты в формате градусы:минуты или точное arccos(4/5).')


def build():
    return {'bookId':BOOK,'lessons':coordinates()+[diagonals(),perpendicular_parameter(),acute_medians()]}


if __name__=='__main__':
    parser=argparse.ArgumentParser();parser.add_argument('--check',action='store_true')
    output=json.dumps(build(),ensure_ascii=False,separators=(',',':'))+'\n'
    if parser.parse_args().check:assert OUT.read_text()==output
    else:OUT.write_text(output)
